  saved.xp=saved.xp&&typeof saved.xp==='object'?saved.xp:{};
  let levelIndex=0,hero='blue',ammo='penicillin',score=0,shots=0,enemies=[],blocks=[],platforms=[],mechanisms=[],shieldActive=false,projectiles=[],pendingRemoval=new Set();
  let active=null,phase='ready',drag=null,aim={x:178,y:403},shotTime=0,levelTime=0,settleUntil=0,paused=false,modalPaused=false,skillUsed=false;
