  const palettes={garden:{sky:'#edf1dd',hill:'#d5e0bf',far:'#e1e8cd',ground:'#bdce9b',top:'#8ca873',light:'#fff1b6',dark:false},water:{sky:'#e4f0e9',hill:'#c4dfd0',far:'#d7e8db',ground:'#a8cbb4',top:'#6d9f8c',light:'#fff0bc',dark:false},cloud:{sky:'#e9eaf3',hill:'#d2d6e8',far:'#e0e0ee',ground:'#b8c4d3',top:'#8b9cb0',light:'#fff4d9',dark:false},lab:{sky:'#e7ece5',hill:'#cbd9c7',far:'#d9e4d3',ground:'#b7c9a4',top:'#839b70',light:'#f5e9ac',dark:false},sunset:{sky:'#f3e9d8',hill:'#e0d3ad',far:'#ebe1c8',ground:'#d0bd8c',top:'#a59c6b',light:'#ffe5a8',dark:false},night:{sky:'#344c5b',hill:'#496373',far:'#40596a',ground:'#657e77',top:'#8ca79a',light:'#f9e5a4',dark:true}};
