  function label(text,x,y,size,color,align='left',weight=600){ctx.font=`${weight} ${size}px Nunito,"Noto Sans SC",sans-serif`;ctx.textAlign=align;ctx.fillStyle=color;ctx.fillText(text,x,y);}
