  function drawTrajectory(){if(phase!=='ready')return;const p=drag;if(!p){const pulse=1+Math.sin(performance.now()*.003)*.08;ctx.save();ctx.setLineDash([4,7]);ctx.beginPath();ctx.arc(ANCHOR.x,ANCHOR.y,31*pulse,0,Math.PI*2);ctx.strokeStyle='#90aa7445';ctx.lineWidth=1.5;ctx.stroke();ctx.restore();return;}let x=p.x,y=p.y,vx=(ANCHOR.x-p.x)*.205,vy=(ANCHOR.y-p.y)*.205;for(let i=0;i<100;i++){vx*=.9992;vy=vy*.9992+.3889;x+=vx;y+=vy;if(y>FLOOR-12)break;if(i%4===0){ellipse(x,y,Math.max(1.5,4-i*.025),Math.max(1.5,4-i*.025),`rgba(91,120,73,${.65-i*.005})`);}}}
