  function frame(now){const rawElapsed=Math.max(0,now-lastTime),elapsed=Math.min(rawElapsed,100);lastTime=now;accumulator+=elapsed;if(paused||modalPaused)accumulator=0;let steps=0;while(accumulator>=STEP&&steps<12){tick(STEP);accumulator-=STEP;steps++;}updateCamera(elapsed);draw(now);frameSamples.push(rawElapsed);if(now-metricsAt>=1000){const sorted=frameSamples.sort((a,b)=>a-b);canvas.dataset.frameP95=String(Math.round(sorted[Math.floor(sorted.length*.95)]||0));canvas.dataset.fps=String(Math.round(1000/(frameSamples.reduce((a,b)=>a+b,0)/frameSamples.length||16.7)));canvas.dataset.camera=String(Math.round(view.left));frameSamples=[];metricsAt=now;}requestAnimationFrame(frame);}
