  function showMap(){showModal('OUR LITTLE ADVENTURE',`<h2>八个小世界，等我们一起守护。</h2><p class="modal-lead">可以按顺序出发，也可以自由选关。获得的星星会留在这个浏览器里。</p><div class="map-grid">${levels.map((l,i)=>`<button class="map-card" data-level="${i}"><strong>${String(i+1).padStart(2,'0')}</strong><b>${l.title}</b><small>${l.subtitle.split(' · ')[0]}</small><em>${'★'.repeat(saved.stars[i])+'☆'.repeat(3-saved.stars[i])}</em></button>`).join('')}</div>`);document.querySelectorAll('[data-level]').forEach(b=>b.onclick=()=>{closeModal();loadLevel(Number(b.dataset.level));});}
  function showHelp(){showModal('A LITTLE FIELD GUIDE',`<h2>把勇气，弹射出去。</h2><p class="modal-lead">一支胶囊、一点点角度，加上全家的奇思妙想。击败所有小病原体，就算守护成功！</p><div class="help-steps"><div class="help-step"><span>↙</span><b>01　向后拉，松手发射</b><p>拖拽弹射台上的胶囊，虚线会预览轨迹。也可在画面左半边拖动。手机竖屏会放大角色并跟随飞行，点“查看全场”可观察目标，再点“放大视角”回来瞄准。瞄准支撑点，让积木帮你。</p></div><div class="help-step"><span>ϟ</span><b>02　飞行中，发动技能</b><p>点击画面或技能按钮：蓝色队员向前冲刺，橙色队员产生范围震波，NABO 释放守护脉冲。每发一次技能。</p></div><div class="help-step"><span>✦</span><b>03　用得巧，星星多</b><p>在画面下方选择补给，点“药敏扫描”查看匹配。不同菌种和耐药机制各有应对；匹配命中减 2 点，结构冲击减 1 点。少用补给可得更多星星。</p></div></div><p class="modal-lead">键盘：方向键调整角度与力度 · 空格发射 · E 发动技能 · R 重来 · Esc 暂停</p><div class="guide-note">✚ 抗生素只针对细菌，对病毒不起作用。免疫护盾、冲刺和震波都是虚构的游戏机制，不代表具体治疗方法。<a href="https://www.cdc.gov/antibiotic-use/about/" target="_blank" rel="noopener">知识来源：CDC</a></div>`);}
